#!/usr/bin/env python3
"""baseline.py - flag users whose upload volume today is far above their own baseline.
Usage: python3 baseline.py upload_mb.csv YYYY-MM-DD   (CSV columns: date,user,mb_out)"""
import csv
import statistics
import sys
from collections import defaultdict

THRESHOLD = 3.0      # alert when today is more than 3 standard deviations above normal
MIN_HISTORY = 14     # days of history required before a baseline is trusted


def main(path, today):
    history, current = defaultdict(list), {}
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            mb = float(row["mb_out"])
            if row["date"] == today:
                current[row["user"]] = mb
            else:
                history[row["user"]].append(mb)

    for user, mb in sorted(current.items()):
        past = history.get(user, [])
        if len(past) < MIN_HISTORY:
            print(f"{user:<11}{mb:>9.1f} MB  baseline=n/a               REVIEW (new user)")
            continue
        mean = statistics.mean(past)
        stdev = statistics.pstdev(past) or 1.0          # avoid division by zero
        z = (mb - mean) / stdev
        flag = "ANOMALY" if z > THRESHOLD else "ok"
        print(f"{user:<11}{mb:>9.1f} MB  mean={mean:>8.1f}  z={z:>6.1f}  {flag}")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

